head.script:
scwin.screenId = "jldfil16401";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님). 진입점 선두 단계.
/**
 * @method
 * @name scwin.init_nowVars
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_Search();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        await scwin.init_rowCopy();
        await scwin.init_loadList();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil16401.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.slc_pageSize_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.slc_pageSize_onchange = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin slc_pageSize_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.search();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16401.slc_pageSize_onchange' }); }
};

/**
 * @event
 * @name scwin.grd_educationList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_educationList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_educationList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_educationList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: fn_SearchRspnDetail (조건 미해석) · fn_SearchChrgDetail (조건 미해석) */
        if (r["chrgTpNm"] === '공시책임자') { if (typeof scwin.searchRspnDetail === 'function') { await scwin.searchRspnDetail(r["disclsEduApplSeq"], r["chrgTpCd"], r["disclsBzChrgAssgnDd"], r["seq"], "N"); } else { console.error('[sdd] 행 동작 미정의: scwin.searchRspnDetail (열 [])'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.searchRspnDetail'); } return; }
        if (typeof scwin.searchChrgDetail === 'function') { await scwin.searchChrgDetail(r["disclsEduApplSeq"], r["seq"], "N"); } else { console.error('[sdd] 행 동작 미정의: scwin.searchChrgDetail (열 [])'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.searchChrgDetail'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_educationList.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/support/education.do",
        ref: "dma_SearchReq",
        target: "dlt_educationList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil16401.tx_fn_Search" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_67").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

/**
 * @method
 * @name scwin.tx_fn_SearchRspnDetail
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_SearchRspnDetail = async function () {
    const sbmOptions = {
        id: "tx_fn_SearchRspnDetail",
        method: "post",
        action: "/support/eduRspn.do",
        ref: "dma_SearchRspnDetailReq",
        target: "dlt_educationList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil16401.tx_fn_SearchRspnDetail" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_SearchChrgDetail
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_SearchChrgDetail = async function () {
    const sbmOptions = {
        id: "tx_fn_SearchChrgDetail",
        method: "post",
        action: "/support/eduChrg.do",
        ref: "dma_SearchChrgDetailReq",
        target: "dlt_educationList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil16401.tx_fn_SearchChrgDetail" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.grd_educationList_fmt_chrgTpNm
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_educationList_fmt_chrgTpNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_educationList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "chrgTpNm") ?? '') : '');
        if (v === '공시책임자') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + (console.error('[sdd] 미실현 라벨 갈래: chrgTpNm (expression)'), String(data ?? '')) + '</a>'; }
        return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + (console.error('[sdd] 미실현 라벨 갈래: chrgTpNm (expression)'), String(data ?? '')) + '</a>';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_educationList.chrgTpNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.eduForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('method', 'searchSaveEducationList');
    frm.action = 'education.do';
    await scwin.tx_fn_Search();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchRspnDetail
 * @author Inswave
 * @date 2026. 09. 29
 * @param disclsEduApplSeq chrgTpCd disclsBzChrgAssgnDd seq editAvailYn
 * @returns
 * @hidden N
*/
scwin.searchRspnDetail = async function (disclsEduApplSeq, chrgTpCd, disclsBzChrgAssgnDd, seq, editAvailYn) {
    /* sdd-asis-lifecycle:begin fn_SearchRspnDetail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.eduForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('method', 'findEducationResponsibilityDetail');
    $c.util.getComponent('dma_SearchReq').set('disclsEduApplSeq', disclsEduApplSeq);
    $c.util.getComponent('dma_SearchReq').set('chrgTpCd', chrgTpCd);
    $c.util.getComponent('dma_SearchReq').set('disclsBzChrgAssgnDd', disclsBzChrgAssgnDd);
    $c.util.getComponent('dma_SearchReq').set('seq', seq);
    $c.util.getComponent('dma_SearchReq').set('editAvailYn', editAvailYn);
    frm.action = 'eduRspn.do';
    { const nr = await scwin.tx_fn_SearchRspnDetail(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil16403/jldfil16403.xml", { "method": 'findEducationResponsibilityDetail', "disclsEduApplSeq": disclsEduApplSeq, "chrgTpCd": chrgTpCd, "disclsBzChrgAssgnDd": disclsBzChrgAssgnDd, "seq": seq, "editAvailYn": editAvailYn }); } };
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchChrgDetail
 * @author Inswave
 * @date 2026. 09. 29
 * @param disclsEduApplSeq seq editAvailYn
 * @returns
 * @hidden N
*/
scwin.searchChrgDetail = async function (disclsEduApplSeq, seq, editAvailYn) {
    /* sdd-asis-lifecycle:begin fn_SearchChrgDetail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.eduForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('method', 'findEducationChargeDetail');
    $c.util.getComponent('dma_SearchReq').set('disclsEduApplSeq', disclsEduApplSeq);
    $c.util.getComponent('dma_SearchReq').set('seq', seq);
    $c.util.getComponent('dma_SearchReq').set('editAvailYn', editAvailYn);
    frm.action = 'eduChrg.do';
    { const nr = await scwin.tx_fn_SearchChrgDetail(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil16404/jldfil16404.xml", { "method": 'findEducationChargeDetail', "disclsEduApplSeq": disclsEduApplSeq, "seq": seq, "editAvailYn": editAvailYn }); } };
    /* sdd-asis-lifecycle:end */
};



/**
 * @event
 * @name scwin.krxpage_pagenavigator_67_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_67_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_SearchReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_67.page' }); } scwin.tx_fn_Search(); };
